const input = $input.first().json;
const body = input.body || input;
const { whatsapp } = body;

if (!whatsapp) {
  throw new Error('Falta el campo requerido: whatsapp');
}

const wa = String(whatsapp).replace(/'/g, "''");

const query = `SELECT
  (SELECT to_jsonb(a) FROM alumnos a WHERE a.whatsapp = '${wa}' LIMIT 1) AS alumno,
  (SELECT to_jsonb(l) FROM leads l WHERE l.whatsapp = '${wa}' ORDER BY l.created_at DESC LIMIT 1) AS lead,
  (
    SELECT jsonb_agg(to_jsonb(h) || jsonb_build_object('alumno_horario_id', ah.id, 'fecha_inscripcion', ah.fecha_inscripcion))
    FROM alumnos_horarios ah
    JOIN horarios h ON h.id = ah.horario_id
    JOIN alumnos a2 ON a2.id = ah.alumno_id
    WHERE a2.whatsapp = '${wa}' AND ah.activo = true
  ) AS horarios_activos,
  (
    SELECT jsonb_agg(p ORDER BY (p->>'created_at') DESC)
    FROM (
      SELECT to_jsonb(p2) AS p
      FROM pagos p2
      JOIN alumnos a3 ON a3.id = p2.alumno_id
      WHERE a3.whatsapp = '${wa}'
      ORDER BY p2.created_at DESC
      LIMIT 3
    ) sub
  ) AS pagos_recientes;`;

return [{ json: { query } }];

const result = $input.first().json || {};

const alumno = result.alumno || null;
const lead = result.lead || null;
const horarios_activos = result.horarios_activos || [];
const pagos_recientes = result.pagos_recientes || [];

let tipo = 'ninguno';
if (alumno) tipo = 'alumno';
else if (lead) tipo = 'lead';

return [{
  json: {
    encontrado: tipo !== 'ninguno',
    tipo,
    alumno,
    lead,
    horarios_activos,
    pagos_recientes
  }
}];
